SELECT P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, COUNT(*) VEZES, MAX(D.DIA) ULTIMA, ROUND(AVG(D.HUMOR), 1) HUMOR FROM PRATICA_DIARIO D JOIN PRATICAS P ON P.ID = D.PRATICA_ID JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID GROUP BY P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID, V.YT_VIDEO_ID, V.TITULO, C.NOME ORDER BY MAX(D.DIA) DESC, COUNT(*) DESC LIMIT 100